values ('fq_merid_061', 'Deep Infrastructure', 'exploration', 'S', 'MERIDIAN_CARTEL', 'SEVERANCE_FAULTLINE', 'The Severance Faultline is rich in energy assets. The Cartel will build extraction infrastructure here. First: secure the construction site. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 60, "reputation_required": 3540, "required_quests": ["fq_merid_060"]}'::jsonb, '[{"type": "travel", "target": "SEVERANCE_FAULTLINE", "count": 1, "desc": "Enter the Severance Faultline.", "description": "Travel to SEVERANCE FAULTLINE. (Travel to: Severance Faultline, Shattered Heart)"}, {"type": "collect", "target": "monster_material", "count": 3, "desc": "Survey infrastructure opportunities.", "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1600, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_062', false, NULL, NULL, NULL, 'quest_meridian.json', 60)
