values ('fq_merid_062', 'Energy Asset Acquisition', 'hunt', 'S', 'MERIDIAN_CARTEL', 'SEVERANCE_FAULTLINE', 'Aethel Iron Carapaces contain compressed energy minerals. (Location: Severance Faultline, Kip) Acquire the assets.', '{"npc_id": "npc_ruin_diver", "name": "Kip", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 61, "reputation_required": 3600, "required_quests": ["fq_merid_061"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Acquire Carapace energy assets.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "crystal_core", "count": 3, "desc": "Prepare energy mineral shipments.", "description": "Collect crystal core (x3). [Item: Crystal Core]"}]'::jsonb, '{"exp": 5200, "currency": 2600, "crd": 1300, "rep": 1700, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_063', false, NULL, NULL, NULL, 'quest_meridian.json', 61)
