values ('fq_merid_063', 'Tyrant Real Estate', 'boss', 'S', 'MERIDIAN_CARTEL', 'SEVERANCE_FAULTLINE', 'Crystal Tyrants occupy prime real estate on the faultline. (Location: Severance Faultline, Don Vercelli) Evict them. Cartel Development is moving in.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 62, "reputation_required": 3660, "required_quests": ["fq_merid_062"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Evict Tyrant tenants.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "File real estate claims.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_064', false, NULL, NULL, NULL, 'quest_meridian.json', 62)
