values ('fq_merid_064', 'Jotunn Eminent Domain', 'boss', 'S', 'MERIDIAN_CARTEL', 'SEVERANCE_FAULTLINE', 'Gigantic Jotunns refuse to relocate. (Location: Severance Faultline, Don Vercelli) Exercise eminent domain — the Cartel way.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 63, "reputation_required": 3720, "required_quests": ["fq_merid_063"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Exercise eminent domain.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "File domain claim paperwork.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2100, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_065', false, NULL, NULL, NULL, 'quest_meridian.json', 63)
