values ('fq_merid_065', 'Power Plant Acquisition', 'exploration', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is the ultimate power plant. The Cartel will acquire it and sell the energy at premium rates. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 64, "reputation_required": 3780, "required_quests": ["fq_merid_064"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "desc": "Enter the Aethel Siphon Core.", "description": "Travel to AETHEL SIPHON CORE. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 2, "desc": "Complete power plant valuation.", "description": "Collect raw aethel fragment (x2). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_066', false, NULL, NULL, NULL, 'quest_meridian.json', 64)
