values ('fq_merid_066', 'Core Asset Security', 'hunt', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'Hostile entities are depreciating Core asset values. (Location: Aethel Siphon Core, Don Vercelli) Secure the investment.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 65, "reputation_required": 3840, "required_quests": ["fq_merid_065"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "desc": "Secure Core investments.", "description": "Defeat Aethel Abyssal Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Eliminate asset depreciation risks.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 5800, "currency": 2900, "crd": 1450, "rep": 1900, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_067', false, NULL, NULL, NULL, 'quest_meridian.json', 65)
