values ('fq_merid_067', 'Behemoth Liability', 'boss', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths are a liability on the Core balance sheet. (Location: Aethel Siphon Core, Don Vercelli) Clear the liability.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 3900, "required_quests": ["fq_merid_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Clear Behemoth liability.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "File clean balance sheet.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2000, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_068', false, NULL, NULL, NULL, 'quest_meridian.json', 66)
