values ('fq_merid_068', 'Rift Market Disruption', 'hunt', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'Rift Stalkers disrupt Core energy markets. (Location: Aethel Siphon Core, Don Vercelli) Eliminate the disruption. Markets must be stable.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 67, "reputation_required": 3960, "required_quests": ["fq_merid_067"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Eliminate market disruption.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "collect", "target": "rift_claw_fragment", "count": 1, "desc": "Confirm market stability.", "description": "Collect rift claw fragment (x1). [Item: Rift Claw Fragment]"}]'::jsonb, '{"exp": 6400, "currency": 3200, "crd": 1600, "rep": 2100, "items": [{"item_id": "dark_energy_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_069', false, NULL, NULL, NULL, 'quest_meridian.json', 67)
