values ('fq_merid_069', 'The Gravity Dividend', 'story', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'The Gravity Titan represents the largest potential dividend in Xylos history. (Location: Aethel Siphon Core, Don Vercelli) Whoever controls gravity controls the market. Prepare the acquisition.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 68, "reputation_required": 230, "required_quests": ["fq_merid_068"]}'::jsonb, '[{"type": "collect", "target": "monster_material", "count": 3, "desc": "Complete Gravity Titan dividend analysis.", "description": "Collect monster material (x3). [Item: Monster Material]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Eliminate Jotunn competitor for the dividend.", "description": "Defeat Gigantic Jotunn (x1)."}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "gravity_well_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_070', false, NULL, NULL, NULL, 'quest_meridian.json', 68)
