values ('fq_merid_071', 'The Prime Monopoly', 'exploration', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'The Prima Materia Forge produces the rarest materials in existence. The Cartel will hold the monopoly on all Forge output. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 70, "reputation_required": 4140, "required_quests": ["fq_merid_070"]}'::jsonb, '[{"type": "travel", "target": "PRIMA_MATERIA_FORGE", "count": 1, "desc": "Enter the Prima Materia Forge.", "description": "Travel to PRIMA MATERIA FORGE. (Travel to: Prima Materia Forge, Shattered Heart)"}, {"type": "collect", "target": "void_core", "count": 2, "desc": "Establish Forge monopoly framework.", "description": "Collect void core (x2). [Item: Void Core]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "raw_aethel_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_072', false, NULL, NULL, NULL, 'quest_meridian.json', 70)
