values ('fq_merid_072', 'Anti-Trust Enforcement', 'hunt', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Ancient Forge defenses are anti-competitive. (Location: Prima Materia Forge, Don Vercelli) The Cartel files an anti-trust motion — enforced by firepower.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 71, "reputation_required": 4200, "required_quests": ["fq_merid_071"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Enforce anti-trust against defenses.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "carapace_fragment", "count": 1, "desc": "File anti-trust enforcement report.", "description": "Collect carapace fragment (x1). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2100, "items": [{"item_id": "rusted_cybernetic_arm", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_073', false, NULL, NULL, NULL, 'quest_meridian.json', 71)
