values ('fq_merid_073', 'Quality Control', 'boss', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Corrupted Behemoths are contaminating Forge output. (Location: Prima Materia Forge, Don Vercelli) This is a quality control disaster. Implement immediate recall and disposal.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 72, "reputation_required": 4260, "required_quests": ["fq_merid_072"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Implement product recall and disposal.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2200, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_074', false, NULL, NULL, NULL, 'quest_meridian.json', 72)
