values ('fq_merid_074', 'Competitor Purge', 'hunt', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Abyssal forces are attempting to steal Forge monopoly. (Location: Prima Materia Forge, Don Vercelli) Purge the competitors.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 73, "reputation_required": 4320, "required_quests": ["fq_merid_073"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "desc": "Purge Abyssal competitors.", "description": "Defeat Aethel Abyssal Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Eliminate competitor leadership.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 6800, "currency": 3400, "crd": 1700, "rep": 2300, "items": [{"item_id": "aethel_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_075', false, NULL, NULL, NULL, 'quest_meridian.json', 73)
