values ('fq_merid_075', 'Forge Union Busting', 'boss', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Jotunns have unionized around the Forge''s heat sources. (Location: Prima Materia Forge, Don Vercelli) The Cartel does not negotiate with unions.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 74, "reputation_required": 4380, "required_quests": ["fq_merid_074"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Bust the Jotunn forge union.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "File union dissolution report.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2400, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_076', false, NULL, NULL, NULL, 'quest_meridian.json', 74)
