values ('fq_merid_076', 'Production Ramp-Up', 'hunt', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'The Cartel board demands 300% production increase. (Location: Prima Materia Forge, Don Vercelli) Clear the production floor of all obstructions.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 75, "reputation_required": 4440, "required_quests": ["fq_merid_075"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "desc": "Clear production obstructions.", "description": "Defeat Aethel Void Channeler (x6)."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "desc": "Confirm 300% production quota met.", "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2500, "items": [{"item_id": "power_regulator_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_077', false, NULL, NULL, NULL, 'quest_meridian.json', 75)
