values ('fq_merid_077', 'Automaton Acquisition', 'boss', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Titan Forge Automatons are superior manufacturing units. (Location: Prima Materia Forge, Don Vercelli) The Cartel wants them on our payroll — or destroyed.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 76, "reputation_required": 4500, "required_quests": ["fq_merid_076"]}'::jsonb, '[{"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "desc": "Acquire or destroy Automaton units.", "description": "Defeat Titan Forge Automaton (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "File acquisition status.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2600, "items": [{"item_id": "processor_cooling_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_078', false, NULL, NULL, NULL, 'quest_meridian.json', 76)
