values ('fq_merid_078', 'Proto Core Liquidation', 'boss', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Titan Proto Cores are failed products. (Location: Prima Materia Forge, Don Vercelli) Liquidate the defective inventory and recover the materials.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 77, "reputation_required": 4560, "required_quests": ["fq_merid_077"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 2, "desc": "Liquidate defective Proto Core inventory.", "description": "Defeat Titan Proto Core (x2)."}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "File material recovery report.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 9000, "currency": 4500, "crd": 2250, "rep": 2800, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_079', false, NULL, NULL, NULL, 'quest_meridian.json', 77)
