values ('fq_merid_079', 'Executive Legend Trial', 'story', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'The Executive Legend trial. (Location: Prima Materia Forge, Don Vercelli) Eliminate both Titan and Harbinger in a single operational cycle. Efficiency is the Cartel way.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 78, "reputation_required": 280, "required_quests": ["fq_merid_078"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Eliminate Titan — operational cost zero.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Eliminate Harbinger — operational cost zero.", "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_080', false, NULL, NULL, NULL, 'quest_meridian.json', 78)
