values ('fq_merid_080', 'Executive Legend', 'story', 'S', 'MERIDIAN_CARTEL', 'PORT_MERIDIAN', 'The Cartel board unanimously votes you Executive Legend. Return to Port Meridian for the shareholder ceremony. Your stock has never been higher. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PORT_MERIDIAN"}'::jsonb, '{"min_level": 79, "reputation_required": 330, "required_quests": ["fq_merid_079"]}'::jsonb, '[{"type": "travel", "target": "PORT_MERIDIAN", "count": 1, "desc": "Return to Port Meridian.", "description": "Travel to PORT MERIDIAN. (Travel to: Port Meridian)"}, {"type": "collect", "target": "refined_scrap", "count": 1, "desc": "Receive your Executive Legend shares.", "description": "Collect refined scrap (x1). [Item: Refined Scrap]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}, {"item_id": "astral_phase_crystal_pure", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_081', false, NULL, NULL, NULL, 'quest_meridian.json', 79)
