values ('fq_merid_081', 'Apex Portfolio', 'story', 'S', 'MERIDIAN_CARTEL', 'HIDDEN_AETHELGARDIAN_CITY', 'The Hidden Aethelgardian City is the ultimate real estate asset. The Cartel will acquire it before any competitor even knows it exists. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 80, "reputation_required": 380, "required_quests": ["fq_merid_080"]}'::jsonb, '[{"type": "travel", "target": "HIDDEN_AETHELGARDIAN_CITY", "count": 1, "desc": "Enter the Hidden Aethelgardian City.", "description": "Travel to HIDDEN AETHELGARDIAN CITY. (Travel to: Hidden Aethelgardian City)"}, {"type": "collect", "target": "monster_material", "count": 3, "desc": "Secure city property deeds.", "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_merid_082', false, NULL, NULL, NULL, 'quest_meridian.json', 80)
