values ('fq_merid_082', 'Property Defense', 'hunt', 'S', 'MERIDIAN_CARTEL', 'HIDDEN_AETHELGARDIAN_CITY', 'City defenses are holdover liabilities from previous ownership. (Location: Hidden Aethelgardian City, Don Vercelli) Clear all liens on the property.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 81, "reputation_required": 4800, "required_quests": ["fq_merid_081"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 8, "desc": "Clear property liens.", "description": "Defeat Aethel Rift Stalker (x8)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "File clear property title.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 8500, "currency": 4200, "crd": 2100, "rep": 2700, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_merid_082', false, NULL, NULL, NULL, 'quest_meridian.json', 81)
