values ('fq_merid_084', 'Apex Drake IPO', 'boss', 'S', 'MERIDIAN_CARTEL', 'SHATTERED_HEART', 'The Apex Ashen Drake is a unique asset with no market equivalent. (Location: Shattered Heart, Don Vercelli) The Cartel files for an Initial Public Obliteration.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 83, "reputation_required": 4920, "required_quests": ["fq_merid_082"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Execute the Apex Drake IPO.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "drake_heart", "count": 1, "desc": "Receive the IPO completion certificate.", "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "ancient_scale", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_085', false, NULL, NULL, NULL, 'quest_meridian.json', 82)
