values ('fq_merid_085', 'Apex Harbinger Acquisition', 'boss', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'The Apex Abyss Harbinger is the final void market competitor. (Location: Void Echo Chasm, Don Vercelli) Acquire — permanently.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 84, "reputation_required": 4980, "required_quests": ["fq_merid_084"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Acquire the Apex Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "desc": "Confirm permanent acquisition.", "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_086', false, NULL, NULL, NULL, 'quest_meridian.json', 83)
