values ('fq_merid_087', 'Triple Merger', 'boss', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'The three Apex entities — Drake, Titan, Harbinger — represent the final merger opportunity. (Location: Prima Materia Forge, Don Vercelli) Consolidate the market.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 86, "reputation_required": 5100, "required_quests": ["fq_merid_086"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Consolidate Drake assets.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Consolidate Titan assets.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Consolidate Harbinger assets.", "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 6000, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_088', false, NULL, NULL, NULL, 'quest_meridian.json', 85)
