values ('fq_merid_088', 'The Siphon Takeover', 'exploration', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is now Cartel Energy Division. Complete the corporate takeover and begin energy billing. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 87, "reputation_required": 5160, "required_quests": ["fq_merid_087"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "desc": "Enter Cartel Energy Division HQ.", "description": "Travel to AETHEL SIPHON CORE. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "core_fragment", "count": 5, "desc": "Deploy corporate takeover beacons.", "description": "Collect core fragment (x5). [Item: Core Fragment]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "power_regulator_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_089', false, NULL, NULL, NULL, 'quest_meridian.json', 86)
