values ('fq_merid_089', 'World Engine IPO', 'story', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'The World Engine is the most valuable asset in Xylos history. (Location: Aethel Siphon Core, Don Vercelli) The Cartel takes it public — with us as the sole shareholder.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 88, "reputation_required": 430, "required_quests": ["fq_merid_088"]}'::jsonb, '[{"type": "collect", "target": "core_fragment", "count": 3, "desc": "Secure World Engine ownership deeds.", "description": "Collect core fragment (x3). [Item: Core Fragment]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 2, "desc": "Eliminate competing bidders.", "description": "Defeat Gigantic Jotunn (x2)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_merid_090', false, NULL, NULL, NULL, 'quest_meridian.json', 87)
