values ('fq_merid_090', 'Engine Activation', 'story', 'S', 'MERIDIAN_CARTEL', 'AETHEL_SIPHON_CORE', 'Activate the World Engine. (Location: Aethel Siphon Core, Don Vercelli) When it goes online, the Cartel will own the means of planetary production. Defend your investment.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 89, "reputation_required": 480, "required_quests": ["fq_merid_089"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Defend the investment.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Eliminate investment risks.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Confirm Engine activation and profit.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_merid_091', false, NULL, NULL, NULL, 'quest_meridian.json', 88)
