values ('fq_merid_091', 'Final Liquidation', 'hunt', 'S', 'MERIDIAN_CARTEL', 'SEVERANCE_FAULTLINE', 'The Engine flushes remaining hostile assets. (Location: Severance Faultline, Don Vercelli) Execute the final liquidation sale — everything must go.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 90, "reputation_required": 5340, "required_quests": ["fq_merid_090"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 5, "desc": "Execute Jotunn liquidation.", "description": "Defeat Gigantic Jotunn (x5)."}, {"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Execute Carapace liquidation.", "description": "Defeat Aethel Iron Carapace (x8)."}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_092', false, NULL, NULL, NULL, 'quest_meridian.json', 89)
