values ('fq_merid_092', 'Void Market Closure', 'hunt', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'The void market is saturated. (Location: Void Echo Chasm, Don Vercelli) Close all remaining void positions and claim final dividends.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 91, "reputation_required": 5400, "required_quests": ["fq_merid_091"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Close Abyssal positions.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "VOID_REAVER", "count": 10, "desc": "Close Void positions.", "description": "Defeat Void Reaver (x10)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_merid_093', false, NULL, NULL, NULL, 'quest_meridian.json', 90)
