values ('fq_merid_093', 'Tyrant Bankruptcy', 'boss', 'S', 'MERIDIAN_CARTEL', 'SHATTERED_HEART', 'Crystal Tyrants file for bankruptcy — Chapter 7, total liquidation. (Location: Shattered Heart, Don Vercelli) Execute the court order.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 92, "reputation_required": 5460, "required_quests": ["fq_merid_092"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 3, "desc": "Execute Chapter 7 liquidation.", "description": "Defeat Crystal Tyrant (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Certify bankruptcy complete.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 4}], "reputation": 50}'::jsonb, false, false, 'fq_merid_094', false, NULL, NULL, NULL, 'quest_meridian.json', 91)
