values ('fq_merid_094', 'Forge Final Quarter', 'hunt', 'S', 'MERIDIAN_CARTEL', 'PRIMA_MATERIA_FORGE', 'Final quarter earnings report. (Location: Prima Materia Forge, Don Vercelli) Maximize Forge output by eliminating all production hindrances.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 93, "reputation_required": 5520, "required_quests": ["fq_merid_093"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 8, "desc": "Eliminate production hindrances.", "description": "Defeat Aethel Void Channeler (x8)."}, {"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "desc": "Replace inefficient Automatons.", "description": "Defeat Titan Forge Automaton (x3)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "raw_aethel_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_merid_095', false, NULL, NULL, NULL, 'quest_meridian.json', 92)
