values ('fq_merid_095', 'Expanse Monopoly', 'hunt', 'S', 'MERIDIAN_CARTEL', 'CRADLE_EXPANSE', 'The Cradle Expanse is now a Cartel-exclusive market. Enforce the monopoly. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 94, "reputation_required": 5580, "required_quests": ["fq_merid_094"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 10, "desc": "Enforce market monopoly.", "description": "Defeat Aethel Rift Stalker (x10)."}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Eliminate residual market competition.", "description": "Defeat Gravity Titan (x1)."}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_096', false, NULL, NULL, NULL, 'quest_meridian.json', 93)
