values ('fq_merid_096', 'Orbital Portfolio', 'hunt', 'S', 'MERIDIAN_CARTEL', 'ORBITAL_SENTINEL_COMMAND', 'The orbital portfolio requires quarterly maintenance. (Location: Orbital Sentinel Command, Don Vercelli) Clear all orbital holdings of hostile entities.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 95, "reputation_required": 5640, "required_quests": ["fq_merid_095"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 10, "desc": "Maintain orbital holdings.", "description": "Defeat Aethel Iron Carapace (x10)."}, {"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Clear orbital liabilities.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 3800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_merid_097', false, NULL, NULL, NULL, 'quest_meridian.json', 94)
