values ('fq_merid_099', 'Eternity CEO Trial', 'story', 'S', 'MERIDIAN_CARTEL', 'VOID_ECHO_CHASM', 'The deepest Void Echo Chasm holds the final board meeting. Defeat the Eternal forms of Titan and Harbinger. The Cartel board demands your ascension. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 98, "reputation_required": 630, "required_quests": ["fq_merid_098"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "desc": "Attend the final board meeting.", "description": "Travel to VOID ECHO CHASM. (Travel to: Void Echo Chasm)"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Vote out the Eternal Gravity Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Vote out the Eternal Abyss Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "desc": "CLAIM THE ETERNITY CEO SEAL.", "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 25000, "currency": 12000, "crd": 6000, "rep": 8000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_merid_100', false, NULL, NULL, NULL, 'quest_meridian.json', 97)
