values ('fq_merid_100', 'Eternity CEO', 'story', 'SS', 'MERIDIAN_CARTEL', 'PORT_MERIDIAN', 'The market has spoken. The shareholders have voted. You are now the ETERNITY CEO — the eternal majority shareholder of Xylos itself. Return to Port Meridian. Every contract. Every deal. Every liquidation. It all led here. Profit is eternal. Quest giver: Don Vercelli at Port Meridian Cartel Headquarters.', '{"npc_id": "npc_cartel_boss", "name": "Don Vercelli", "location": "PORT_MERIDIAN"}'::jsonb, '{"min_level": 99, "reputation_required": 680, "required_quests": ["fq_merid_099"]}'::jsonb, '[{"type": "travel", "target": "PORT_MERIDIAN", "count": 1, "desc": "Return to Port Meridian as Eternity CEO.", "description": "Travel to PORT MERIDIAN. (Travel to: Port Meridian)"}, {"type": "interact", "target": "npc_cartel_boss", "count": 1, "desc": "Receive the Eternity CEO charter from Executive Director Silas.", "description": "Speak with npc cartel boss. (Don Vercelli at Port Meridian Cartel Headquarters)"}]'::jsonb, '{"exp": 50000, "currency": 25000, "crd": 0, "rep": 10000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 5}, {"item_id": "ceo_seal", "quantity": 1}], "reputation": 5}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_meridian.json', 98)
