values ('fq_omni_004', 'Zero Tolerance for Waste', 'story', 'D', 'OMNICORP', 'HIGHLAND_PLATEAU', 'OmniCorp''s resource optimization assessment of the Highland Plateau flagged Highland Goatlings as a drain on the plateau''s nutrient substrate — a substrate OmniCorp intends to use for hydroponic mineral extraction. Director Vey''s briefing contains a single metric: removal cost versus projected extraction gain over three fiscal years. The math is unambiguous. The Goatlings are not a problem with a solution; they are a resource allocation decision that has already been made. Execute it. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Astra Vey", "location": "HIGHLAND_PLATEAU"}'::jsonb, '{"min_level": 3, "reputation_required": 15, "required_quests": ["fq_omni_003"]}'::jsonb, '[{"type": "kill", "target": "HIGHLAND_GOATLING", "count": 5, "desc": "Terminate Goatling resource drain.", "description": "Defeat Highland Goatling (x5)."}, {"type": "collect", "target": "goat_horn", "count": 1, "desc": "File resource reclamation report.", "description": "Collect goat horn (x1). [Item: Goat Horn]"}]'::jsonb, '{"exp": 80, "currency": 50, "crd": 0, "rep": 50, "items": [{"item_id": "raw_hide", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_omni_005', false, NULL, NULL, NULL, 'quest_omnicorp.json', 3)
