values ('fq_omni_005', 'Class Module Installation', 'tutorial', 'D', 'OMNICORP', 'THE_SPIRE', 'Your performance metrics have exceeded OmniCorp''s baseline projections. Director Astra Vey''s note in your personnel file is brief and specific: ''Asset efficiency: 134%. Recommend module upgrade.'' The Spire — OmniCorp''s arcology headquarters, a needle of glass and processed aethel that dominates the Xylos skyline — houses the Class Module installation suite on its seventh floor. Your function is about to be optimized. What you become here will determine OmniCorp''s investment in your continued operation.', '{"npc_id": "npc_omnicorp_class_trainer", "name": "Director Astra Vey", "location": "THE_SPIRE"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_omni_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_omnicorp_class_trainer", "count": 1, "desc": "Report to Director Astra Vey for module installation.", "description": "Speak with npc omnicorp class trainer. (Director Astra Vey at The Spire Advanced Division)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "desc": "Select your Class Module.", "description": "Speak with class change screen."}, {"type": "kill", "target": "PLATEAU_DRONE", "count": 3, "desc": "Demonstrate module functionality on Stone Armadillos.", "description": "Defeat Plateau Drone (x3)."}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_steel_broadsword", "quantity": 1}, {"item_id": "arm_iron_plate", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_omni_006', true, 'on_quest_complete', 4, 'fq_omni_004', 'quest_omnicorp.json', 4)
