values ('fq_omni_006', 'Zone Delta: Operational Assessment', 'story', 'D', 'OMNICORP', 'EXTRACTION_ZONE_DELTA', 'Extraction Zone Delta is OmniCorp''s primary resource harvesting site on Xylos — a zone of automated drilling platforms, mineral processors, and survey grids that represents the company''s most significant capital investment on the planet. Chief Barrett runs it with the intensity of someone who understands that if Zone Delta underperforms, the Xylos investment mandate gets reviewed at OmniCorp''s galactic board level. Director Vey is watching the extraction metrics. So is everyone above her. Conduct the assessment.', '{"npc_id": "npc_extraction_chief", "name": "Director Astra Vey", "location": "EXTRACTION_ZONE_DELTA"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_omni_005"]}'::jsonb, '[{"type": "travel", "target": "EXTRACTION_ZONE_DELTA", "count": 1, "desc": "Enter Extraction Zone Delta.", "description": "Travel to EXTRACTION ZONE DELTA. (Travel to: Extraction Zone Delta)"}, {"type": "collect", "target": "core_fragment", "count": 2, "desc": "Complete extraction zone assessment.", "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_omni_007', false, NULL, NULL, NULL, 'quest_omnicorp.json', 5)
