values ('fq_omni_013', 'Obsolete Combat Algorithms', 'story', 'C', 'OMNICORP', 'SECURE_MINING_GRID', 'The Grid Defenders were the previous operators'' frontline combat units — built to a standard that was impressive for its era and is now, by OmniCorp''s metrics, 340% below current combat hardware benchmarks. (Location: Secure Mining Grid, Tech Officer 404) Tech Officer 404 has completed the obsolescence analysis. Director Vey has reviewed it. The conclusion is standard OmniCorp doctrine: hardware that cannot be upgraded to current specifications is hardware that needs to be cleared from the asset inventory. Begin the replacement cycle.', '{"npc_id": "npc_omnicorp_technician", "name": "Director Astra Vey", "location": "SECURE_MINING_GRID"}'::jsonb, '{"min_level": 12, "reputation_required": 50, "required_quests": ["fq_omni_012"]}'::jsonb, '[{"type": "kill", "target": "GRID_DEFENDER", "count": 5, "desc": "Replace Grid Defenders.", "description": "Defeat Grid Defender (x5)."}, {"type": "collect", "target": "refined_scrap", "count": 1, "desc": "Upload new combat algorithm.", "description": "Collect refined scrap (x1). [Item: Refined Scrap]"}]'::jsonb, '{"exp": 360, "currency": 190, "crd": 0, "rep": 200, "items": [{"item_id": "neural_interface_socket", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_omni_014', false, NULL, NULL, NULL, 'quest_omnicorp.json', 11)
