values ('fq_omni_014', 'Central Node Override', 'story', 'C', 'OMNICORP', 'SECURE_MINING_GRID', 'The Grid Assault Units are the previous operators'' most sophisticated hardware — and they control the central processing node that manages the entire Secure Mining Grid''s operation. OmniCorp cannot take full operational control of the Grid until the Assault Units are cleared and OmniCorp''s own management protocols are installed. Director Vey frames this as a critical path item on the Xylos acquisition timeline. The Warden AI will handle the installation. You handle the override. Maximum force authorized.', '{"npc_id": "npc_grid_security", "name": "Director Astra Vey", "location": "SECURE_MINING_GRID"}'::jsonb, '{"min_level": 13, "reputation_required": 55, "required_quests": ["fq_omni_013"]}'::jsonb, '[{"type": "kill", "target": "GRID_ASSAULT_UNIT", "count": 3, "desc": "Override Grid Assault Unit protocols.", "description": "Defeat Grid Assault Unit (x3)."}, {"type": "collect", "target": "sensor_chip", "count": 1, "desc": "Secure central node access.", "description": "Collect sensor chip (x1). [Item: Sensor Chip]"}]'::jsonb, '{"exp": 450, "currency": 240, "crd": 0, "rep": 240, "items": [{"item_id": "tactical_sensor_cluster", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_omni_015', false, NULL, NULL, NULL, 'quest_omnicorp.json', 12)
