values ('fq_omni_018', 'Unauthorized Sector Seizure', 'story', 'C', 'OMNICORP', 'SECURE_MINING_GRID', 'The Grid Assault Unit cluster has done something the Warden AI classifies as unprecedented in its operational history: it has seized Grid Sector 7, locked OmniCorp''s protocols out of the local node, and appears to be executing an autonomous objective that was not in its original programming. (Location: Secure Mining Grid, Warden AI) Tech Officer 404''s analysis is alarming and concise: the cluster is exhibiting emergent behavior. Director Vey''s response to this is two words: ''Terminate it.'' She is already forwarding the incident report to OmniCorp''s R&D division.', '{"npc_id": "npc_grid_security", "name": "Director Astra Vey", "location": "SECURE_MINING_GRID"}'::jsonb, '{"min_level": 17, "reputation_required": 75, "required_quests": ["fq_omni_017"]}'::jsonb, '[{"type": "kill", "target": "GRID_ASSAULT_UNIT", "count": 5, "desc": "Terminate unauthorized processes.", "description": "Defeat Grid Assault Unit (x5)."}, {"type": "collect", "target": "scrap_core", "count": 1, "desc": "Confirm sector 7 reclaimed.", "description": "Collect scrap core (x1). [Item: Scrap Core]"}]'::jsonb, '{"exp": 600, "currency": 330, "crd": 0, "rep": 350, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_omni_019', false, NULL, NULL, NULL, 'quest_omnicorp.json', 16)
