values ('fq_omni_019', 'Signal Interference: Source Located', 'story', 'C', 'OMNICORP', 'SECURE_MINING_GRID', 'The Resonance Echo that formed in Grid Sector 7 during the cluster''s autonomous operations has created a signal interference pattern across all grid frequencies — which is why the Warden AI''s communications have been degraded and why OmniCorp''s management protocols have been running at 40% bandwidth for the past six hours. (Location: Secure Mining Grid, Director Sterling) Director Vey has reviewed the interference signature against OmniCorp''s signal library. She finds it ''consistent with known Aethelgardian communication formats.'' This information goes nowhere outside OmniCorp. Eliminate the source.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Astra Vey", "location": "SECURE_MINING_GRID"}'::jsonb, '{"min_level": 18, "reputation_required": 80, "required_quests": ["fq_omni_018"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "desc": "Eliminate Resonance Echo interference.", "description": "Defeat Resonance Echo (x1)."}, {"type": "kill", "target": "GRID_ASSAULT_UNIT", "count": 2, "desc": "Clear Assault Unit escorts.", "description": "Defeat Grid Assault Unit (x2)."}]'::jsonb, '{"exp": 800, "currency": 450, "crd": 0, "rep": 450, "items": [{"item_id": "entropy_core", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_omni_020', false, NULL, NULL, NULL, 'quest_omnicorp.json', 17)
