values ('fq_omni_020', 'Advanced Unit Certification', 'story', 'C', 'OMNICORP', 'THE_SPIRE', 'The Secure Mining Grid is at 94% operational efficiency — one point below OmniCorp standard, which Director Vey has flagged as ''within acceptable margin.'' This represents an extraordinary improvement in a compressed timeline, and OmniCorp does not leave extraordinary performance unacknowledged when the performance metrics are this clean. (Location: The Spire, Director Sterling) Return to the Spire. The Advanced Unit certification comes with expanded access credentials and a briefing on the Skybridge Reactor project — the next phase of OmniCorp''s Xylos acquisition plan.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Astra Vey", "location": "THE_SPIRE"}'::jsonb, '{"min_level": 19, "reputation_required": 85, "required_quests": ["fq_omni_019"]}'::jsonb, '[{"type": "travel", "target": "THE_SPIRE", "count": 1, "desc": "Return to the Spire.", "description": "Travel to THE SPIRE. (Travel to: The Spire)"}, {"type": "collect", "target": "thick_gel", "count": 1, "desc": "Receive Advanced Unit certification.", "description": "Collect thick gel (x1). [Item: Thick Gel]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_hp_cell", "quantity": 5}], "reputation": 5}'::jsonb, false, false, 'fq_omni_021', false, NULL, NULL, NULL, 'quest_omnicorp.json', 18)
