values ('fq_omni_021', 'Data Retrieval', 'exploration', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'The Skybridge Reactor contains pre-colonization power systems. Initiate data retrieval from the Reactor''s legacy systems. Quest giver: Engineer Cross at Skybridge Reactor Maintenance Bay.', '{"npc_id": "npc_reactor_engineer", "name": "Engineer Cross", "location": "SKYBRIDGE_REACTOR"}'::jsonb, '{"min_level": 20, "reputation_required": 1140, "required_quests": ["fq_omni_020"]}'::jsonb, '[{"type": "travel", "target": "SKYBRIDGE_REACTOR", "count": 1, "desc": "Enter the Skybridge Reactor.", "description": "Travel to SKYBRIDGE REACTOR. (Travel to: Skybridge Reactor)"}, {"type": "collect", "target": "monster_material", "count": 2, "desc": "Download Reactor schematics.", "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 600, "currency": 350, "crd": 105, "rep": 350, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_omni_022', false, NULL, NULL, NULL, 'quest_omnicorp.json', 19)
