values ('fq_omni_022', 'Assembly Drone Acquisition', 'hunt', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'Titan Assembly Drones are valuable manufacturing units. (Location: Skybridge Reactor, Engineer Cross) Acquire them for Omnicorp R&D — intact or in pieces.', '{"npc_id": "npc_reactor_engineer", "name": "Engineer Cross", "location": "SKYBRIDGE_REACTOR"}'::jsonb, '{"min_level": 21, "reputation_required": 1200, "required_quests": ["fq_omni_021"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_DRONE", "count": 5, "desc": "Acquire Assembly Drones for R&D.", "description": "Defeat Titan Assembly Drone (x5)."}, {"type": "collect", "target": "circuit_fragment", "count": 2, "desc": "Catalog acquired components.", "description": "Collect circuit fragment (x2). [Item: Circuit Fragment]"}]'::jsonb, '{"exp": 650, "currency": 380, "crd": 114, "rep": 380, "items": [{"item_id": "scrap_circuit", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_omni_023', false, NULL, NULL, NULL, 'quest_omnicorp.json', 20)
