values ('fq_omni_023', 'Sentinel Protocol Update', 'boss', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'Titan Assembly Sentinels guard the Reactor core. (Location: Skybridge Reactor, Warden AI) Their security protocols are incompatible with Omnicorp systems. Override.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "SKYBRIDGE_REACTOR"}'::jsonb, '{"min_level": 22, "reputation_required": 1260, "required_quests": ["fq_omni_022"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_SENTINEL", "count": 3, "desc": "Override Sentinel security protocols.", "description": "Defeat Titan Assembly Sentinel (x3)."}, {"type": "collect", "target": "sensor_chip", "count": 1, "desc": "Log core access granted.", "description": "Collect sensor chip (x1). [Item: Sensor Chip]"}]'::jsonb, '{"exp": 750, "currency": 420, "crd": 126, "rep": 450, "items": [{"item_id": "damaged_servo_motor", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_omni_024', false, NULL, NULL, NULL, 'quest_omnicorp.json', 21)
