values ('fq_omni_024', 'Proto Core Analysis', 'boss', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'Titan Proto Cores are failed Titan experiments. (Location: Skybridge Reactor, Engineer Cross) Omnicorp wants the failure data. Extract it from the Cores — forcibly.', '{"npc_id": "npc_reactor_engineer", "name": "Engineer Cross", "location": "SKYBRIDGE_REACTOR"}'::jsonb, '{"min_level": 23, "reputation_required": 1320, "required_quests": ["fq_omni_023"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 2, "desc": "Extract failure data from Proto Cores.", "description": "Defeat Titan Proto Core (x2)."}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "Upload failure analysis.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 850, "currency": 460, "crd": 138, "rep": 480, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_omni_025', false, NULL, NULL, NULL, 'quest_omnicorp.json', 22)
