values ('fq_omni_025', 'Serpent Energy Collection', 'boss', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'Storm Rift Serpents feed on the Reactor''s energy output. (Location: Skybridge Reactor, Director Sterling) This is theft of corporate resources. Recover the stolen energy.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "SKYBRIDGE_REACTOR"}'::jsonb, '{"min_level": 24, "reputation_required": 1380, "required_quests": ["fq_omni_024"]}'::jsonb, '[{"type": "kill", "target": "STORM_RIFT_SERPENT", "count": 2, "desc": "Recover stolen energy from Serpents.", "description": "Defeat Storm Rift Serpent (x2)."}, {"type": "collect", "target": "storm_core", "count": 1, "desc": "Report energy recovery metrics.", "description": "Collect storm core (x1). [Item: Storm Core]"}]'::jsonb, '{"exp": 1000, "currency": 550, "crd": 165, "rep": 550, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_omni_026', false, NULL, NULL, NULL, 'quest_omnicorp.json', 23)
