values ('fq_omni_026', 'Cradle Expanse Monitoring', 'exploration', 'B', 'OMNICORP', 'CRADLE_EXPANSE', 'The Cradle Expanse requires orbital monitoring station deployment. Establish Omnicorp surveillance of the contested zone. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 25, "reputation_required": 1440, "required_quests": ["fq_omni_025"]}'::jsonb, '[{"type": "travel", "target": "CRADLE_EXPANSE", "count": 1, "desc": "Enter the Cradle Expanse.", "description": "Travel to CRADLE EXPANSE. (Travel to: Cradle Expanse)"}, {"type": "collect", "target": "raw_aethel_core", "count": 2, "desc": "Deploy surveillance stations.", "description": "Collect raw aethel core (x2). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 700, "currency": 400, "crd": 120, "rep": 400, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_omni_027', false, NULL, NULL, NULL, 'quest_omnicorp.json', 24)
