values ('fq_omni_027', 'Rift Stalker Observation', 'hunt', 'B', 'OMNICORP', 'CRADLE_EXPANSE', 'Aethel Rift Stalkers are biological anomalies. (Location: Cradle Expanse, Tech Officer 404) Collect specimens for Omnicorp Bio-Division analysis.', '{"npc_id": "npc_omnicorp_technician", "name": "Tech Officer 404", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 26, "reputation_required": 1500, "required_quests": ["fq_omni_026"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 5, "desc": "Collect Rift Stalker specimens.", "description": "Defeat Aethel Rift Stalker (x5)."}, {"type": "collect", "target": "rift_claw_fragment", "count": 1, "desc": "Submit bio-analysis preliminary report.", "description": "Collect rift claw fragment (x1). [Item: Rift Claw Fragment]"}]'::jsonb, '{"exp": 750, "currency": 430, "crd": 129, "rep": 430, "items": [{"item_id": "dark_energy_fragment", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_omni_028', false, NULL, NULL, NULL, 'quest_omnicorp.json', 25)
