values ('fq_omni_028', 'Behemoth Specimen', 'boss', 'B', 'OMNICORP', 'CRADLE_EXPANSE', 'Aethel Behemoths contain unique biological power cells. (Location: Cradle Expanse, Tech Officer 404) Harvest them for Omnicorp energy research.', '{"npc_id": "npc_omnicorp_technician", "name": "Tech Officer 404", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 27, "reputation_required": 1560, "required_quests": ["fq_omni_027"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "desc": "Harvest Behemoth power cells.", "description": "Defeat Aethel Behemoth (x2)."}, {"type": "collect", "target": "raw_aethel_core", "count": 1, "desc": "Submit power cell analysis.", "description": "Collect raw aethel core (x1). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 900, "currency": 520, "crd": 156, "rep": 520, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_omni_029', false, NULL, NULL, NULL, 'quest_omnicorp.json', 26)
