values ('fq_omni_029', 'Sentinel Reactivation', 'boss', 'B', 'OMNICORP', 'SKYBRIDGE_REACTOR', 'Titan Assembly Sentinels auto-reactivate every 72 hours. (Location: Skybridge Reactor, Warden AI) Implement permanent shutdown procedure.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "SKYBRIDGE_REACTOR"}'::jsonb, '{"min_level": 28, "reputation_required": 1620, "required_quests": ["fq_omni_028"]}'::jsonb, '[{"type": "kill", "target": "TITAN_ASSEMBLY_SENTINEL", "count": 4, "desc": "Implement permanent shutdown.", "description": "Defeat Titan Assembly Sentinel (x4)."}, {"type": "collect", "target": "sensor_chip", "count": 1, "desc": "Confirm permanent shutdown.", "description": "Collect sensor chip (x1). [Item: Sensor Chip]"}]'::jsonb, '{"exp": 850, "currency": 480, "crd": 144, "rep": 480, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_omni_030', false, NULL, NULL, NULL, 'quest_omnicorp.json', 27)
