values ('fq_omni_030', 'Firmware Update', 'story', 'B', 'OMNICORP', 'THE_SPIRE', 'System analysis indicates Ascension-ready status. (Location: The Spire, Director Astra Vey) Report to Director Astra Vey for Firmware v3.0 installation.', '{"npc_id": "npc_omnicorp_class_trainer", "name": "Director Astra Vey", "location": "THE_SPIRE"}'::jsonb, '{"min_level": 29, "reputation_required": 90, "required_quests": ["fq_omni_029"]}'::jsonb, '[{"type": "interact", "target": "npc_omnicorp_class_trainer", "count": 1, "desc": "Report for Firmware Update installation.", "description": "Speak with npc omnicorp class trainer. (Director Astra Vey at The Spire Advanced Division)"}, {"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "desc": "Field-test Firmware on Resonance Echo.", "description": "Defeat Resonance Echo (x1)."}, {"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "desc": "Stress-test Firmware on Titan Proto Core.", "description": "Defeat Titan Proto Core (x1)."}]'::jsonb, '{"exp": 2500, "currency": 1200, "crd": 360, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}, {"item_id": "astral_phase_crystal_pure", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_omni_031', true, 'on_quest_complete', 29, 'fq_omni_029', 'quest_omnicorp.json', 28)
