values ('fq_omni_031', 'Aerial Monitoring', 'exploration', 'A', 'OMNICORP', 'ORBITAL_SENTINEL_COMMAND', 'Orbital Sentinel Command provides planetary-wide sensor coverage. Omnicorp will integrate its systems with our network. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 30, "reputation_required": 1740, "required_quests": ["fq_omni_030"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "desc": "Report to Orbital Sentinel Command.", "description": "Travel to ORBITAL SENTINEL COMMAND. (Travel to: Orbital Sentinel Command)"}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "Complete orbital systems integration.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 250, "rep": 500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_omni_032', false, NULL, NULL, NULL, 'quest_omnicorp.json', 29)
