values ('fq_omni_036', 'Orbital Network Defense', 'hunt', 'A', 'OMNICORP', 'ORBITAL_SENTINEL_COMMAND', 'Hostile entities probing orbital network nodes. (Location: Orbital Sentinel Command, Director Sterling) Deploy automated defense protocols.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 35, "reputation_required": 2040, "required_quests": ["fq_omni_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Deploy automated defense protocols.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "desc": "Neutralize network intrusion specialists.", "description": "Defeat Aethel Void Channeler (x3)."}]'::jsonb, '{"exp": 1500, "currency": 800, "crd": 400, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_omni_037', false, NULL, NULL, NULL, 'quest_omnicorp.json', 34)
