values ('fq_omni_037', 'Drake System Shutdown', 'boss', 'A', 'OMNICORP', 'CRADLE_EXPANSE', 'The Ashen Drake has re-initialized. (Location: Cradle Expanse, Director Sterling) Execute System Shutdown on the Drake process. No process is immune to termination.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 36, "reputation_required": 2100, "required_quests": ["fq_omni_036"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Execute System Shutdown on Drake.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "drake_heart", "count": 1, "desc": "Confirm Drake process terminated.", "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 900, "items": [{"item_id": "drake_heart", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_omni_038', false, NULL, NULL, NULL, 'quest_omnicorp.json', 35)
