values ('fq_omni_038', 'Grid Expansion', 'hunt', 'A', 'OMNICORP', 'CRADLE_EXPANSE', 'Omnicorp grid expansion into the Expanse faces hostile resistance. (Location: Cradle Expanse, Director Sterling) Override resistance with superior firepower.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 37, "reputation_required": 2160, "required_quests": ["fq_omni_037"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Override hostile resistance.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Confirm grid expansion.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 1700, "currency": 900, "crd": 450, "rep": 900, "items": [{"item_id": "scrap_metal", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_omni_039', false, NULL, NULL, NULL, 'quest_omnicorp.json', 36)
