values ('fq_omni_039', 'Reaver Network Breach', 'boss', 'A', 'OMNICORP', 'CRADLE_EXPANSE', 'Abyssal Reavers are executing a coordinated network breach. (Location: Cradle Expanse, Warden AI) Isolate and terminate all intrusion vectors.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 2220, "required_quests": ["fq_omni_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Isolate intrusion vectors.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "desc": "Terminate Channeler intrusion specialists.", "description": "Defeat Aethel Void Channeler (x3)."}]'::jsonb, '{"exp": 2000, "currency": 1100, "crd": 550, "rep": 1100, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_omni_040', false, NULL, NULL, NULL, 'quest_omnicorp.json', 37)
