values ('fq_omni_040', 'System Master', 'story', 'A', 'OMNICORP', 'THE_SPIRE', 'The System Master certification trial. (Location: The Spire, Director Sterling) Terminate Ashen Drake and two elite threats to prove System Master operational status.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "THE_SPIRE"}'::jsonb, '{"min_level": 39, "reputation_required": 100, "required_quests": ["fq_omni_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Terminate Drake process.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "desc": "Terminate Behemoth process.", "description": "Defeat Aethel Behemoth (x1)."}, {"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "desc": "Terminate Proto Core process.", "description": "Defeat Titan Proto Core (x1)."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_omni_041', false, NULL, NULL, NULL, 'quest_omnicorp.json', 38)
