values ('fq_omni_041', 'Subterranean Analysis', 'exploration', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'The Void Echo Chasm represents a dimensional anomaly. Omnicorp authorizes full analysis. All sensor data will be uploaded to the Spire. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 40, "reputation_required": 2340, "required_quests": ["fq_omni_040"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "desc": "Enter the Void Echo Chasm.", "description": "Travel to VOID ECHO CHASM. (Travel to: Void Echo Chasm)"}, {"type": "collect", "target": "alpha_fang", "count": 3, "desc": "Upload chasm sensor data.", "description": "Collect alpha fang (x3). [Item: Alpha Fang]"}]'::jsonb, '{"exp": 1800, "currency": 900, "crd": 450, "rep": 600, "items": [{"item_id": "void_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_042', false, NULL, NULL, NULL, 'quest_omnicorp.json', 39)
