values ('fq_omni_042', 'Reaver Debug', 'hunt', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Void Reavers are runtime errors in the dimensional fabric. (Location: Void Echo Chasm, Tech Officer 404) Execute Debug Protocol on all Reaver instances.', '{"npc_id": "npc_omnicorp_technician", "name": "Tech Officer 404", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 41, "reputation_required": 2400, "required_quests": ["fq_omni_041"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 6, "desc": "Execute Debug Protocol on Reavers.", "description": "Defeat Void Reaver (x6)."}, {"type": "collect", "target": "void_fragment", "count": 1, "desc": "Upload debug operation log.", "description": "Collect void fragment (x1). [Item: Void Fragment]"}]'::jsonb, '{"exp": 1900, "currency": 950, "crd": 475, "rep": 650, "items": [{"item_id": "void_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_043', false, NULL, NULL, NULL, 'quest_omnicorp.json', 40)
