values ('fq_omni_043', 'Channeler Malware', 'story', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Void Channelers are running unauthorized void-energy scripts. (Location: Void Echo Chasm, Warden AI) Classify as malware. Execute Anti-Malware Protocol.', '{"npc_id": "npc_grid_security", "name": "Warden AI", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 42, "reputation_required": 125, "required_quests": ["fq_omni_042"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "desc": "Execute Anti-Malware Protocol.", "description": "Defeat Aethel Void Channeler (x6)."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "desc": "Confirm malware removal.", "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2100, "currency": 1050, "crd": 525, "rep": 700, "items": [{"item_id": "event_horizon_fragment", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_044', false, NULL, NULL, NULL, 'quest_omnicorp.json', 41)
