values ('fq_omni_044', 'Abyssal Process Termination', 'hunt', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Aethel Abyssal Reavers are high-priority system processes that cannot be terminated through normal means. (Location: Void Echo Chasm, Director Sterling) Deploy Kill Command.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 2520, "required_quests": ["fq_omni_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Deploy Kill Command on Abyssal processes.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Upload Kill Command execution log.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2200, "currency": 1100, "crd": 550, "rep": 750, "items": [{"item_id": "void_crystal_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_045', false, NULL, NULL, NULL, 'quest_omnicorp.json', 42)
