values ('fq_omni_049', 'Heart Sector Analysis', 'exploration', 'S', 'OMNICORP', 'SHATTERED_HEART', 'The Shattered Heart is an unexploited resource sector. Omnicorp authorizes full sector analysis and asset deployment. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 48, "reputation_required": 2820, "required_quests": ["fq_omni_048"]}'::jsonb, '[{"type": "travel", "target": "SHATTERED_HEART", "count": 1, "desc": "Enter the Shattered Heart sector.", "description": "Travel to SHATTERED HEART. (Travel to: Shattered Heart, Shattered Heart)"}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Complete sector analysis.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_050', false, NULL, NULL, NULL, 'quest_omnicorp.json', 47)
