values ('fq_omni_050', 'Resource Extraction', 'boss', 'S', 'OMNICORP', 'SHATTERED_HEART', 'THE DRAKE EXTRACTION OPERATION. (Location: Shattered Heart, Director Sterling) The Ashen Drake is a Class-A energy asset. Extract its core for Omnicorp reactor fuel. Raid Tier-1. Efficiency is the only metric.', '{"npc_id": "npc_omnicorp_executive", "name": "Director Sterling", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 49, "reputation_required": 2880, "required_quests": ["fq_omni_049"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "EXTRACT DRAKE ENERGY CORE.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "DRAKE_MINION", "count": 5, "desc": "Clear Drake Minion obstacles.", "description": "Defeat Drake Minion (x5)."}, {"type": "collect", "target": "drake_scale_fragment", "count": 1, "desc": "Confirm core extraction complete.", "description": "Collect drake scale fragment (x1). [Item: Drake Scale Fragment]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "ancient_scale", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_051', false, NULL, NULL, NULL, 'quest_omnicorp.json', 48)
