values ('fq_omni_051', 'Anti-Virus Protocol', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Soul Fragmenters have multiplied beyond acceptable parameters. (Location: Void Echo Chasm, Warden AI) Execute comprehensive Anti-Virus sweep.', '{"npc_id": "npc_grid_security", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 50, "reputation_required": 2940, "required_quests": ["fq_omni_050"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "desc": "Execute Anti-Virus sweep.", "description": "Defeat Soul Fragmenter (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm virus scan complete.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "brainwave_reader", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_052', false, NULL, NULL, NULL, 'quest_omnicorp.json', 49)
