values ('fq_omni_052', 'Total Void Cleanup', 'hunt', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Operation Total Void Cleanup. (Location: Void Echo Chasm, Director Sterling) All void entities classified as system junk. Execute Disk Cleanup Protocol.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 51, "reputation_required": 3000, "required_quests": ["fq_omni_051"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 8, "desc": "Execute Disk Cleanup on Reavers.", "description": "Defeat Void Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Execute Disk Cleanup on Channelers.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 4500, "currency": 2200, "crd": 1100, "rep": 1500, "items": [{"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_053', false, NULL, NULL, NULL, 'quest_omnicorp.json', 50)
