values ('fq_omni_053', 'Stalker Rootkit', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'A Void Stalker operates as a rootkit in the void network. (Location: Void Echo Chasm, Warden AI) Rootkits must be removed at the kernel level.', '{"npc_id": "npc_grid_security", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 52, "reputation_required": 3060, "required_quests": ["fq_omni_052"]}'::jsonb, '[{"type": "kill", "target": "VOID_STALKER", "count": 1, "desc": "Remove Stalker rootkit.", "description": "Defeat Void Stalker (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm rootkit removal.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "entropy_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_054', false, NULL, NULL, NULL, 'quest_omnicorp.json', 51)
