values ('fq_omni_054', 'Temporal Patch', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Chrono Wraiths exploit temporal vulnerabilities. (Location: Void Echo Chasm, Tech Officer 404) Deploy Temporal Stability Patch across all affected sectors.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 53, "reputation_required": 3120, "required_quests": ["fq_omni_053"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 3, "desc": "Deploy Temporal Stability Patch.", "description": "Defeat Chrono Wraith (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm all patches deployed.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6500, "currency": 3200, "crd": 1600, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_055', false, NULL, NULL, NULL, 'quest_omnicorp.json', 52)
