values ('fq_omni_055', 'Heart Sector Purge', 'hunt', 'S', 'OMNICORP', 'SHATTERED_HEART', 'The Shattered Heart sector contains residual hostile processes. Execute Sector Purge Protocol. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 54, "reputation_required": 3180, "required_quests": ["fq_omni_054"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Execute Sector Purge on Reavers.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "VOID_REAVER", "count": 6, "desc": "Execute Sector Purge on Void Reavers.", "description": "Defeat Void Reaver (x6)."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1700, "items": [{"item_id": "event_horizon_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_056', false, NULL, NULL, NULL, 'quest_omnicorp.json', 53)
