values ('fq_omni_056', 'Jotunn Server Shutdown', 'boss', 'S', 'OMNICORP', 'SHATTERED_HEART', 'Gigantic Jotunns function as organic servers hosting hostile processes. (Location: Shattered Heart, Warden AI) Shut them down.', '{"npc_id": "npc_grid_security", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 55, "reputation_required": 3240, "required_quests": ["fq_omni_055"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Shut down Jotunn servers.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Upload server shutdown log.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_057', false, NULL, NULL, NULL, 'quest_omnicorp.json', 54)
