values ('fq_omni_057', 'Tyrant Hardware Removal', 'boss', 'S', 'OMNICORP', 'SHATTERED_HEART', 'Crystal Tyrants are foreign hardware installations in the Heart sector. (Location: Shattered Heart, Director Sterling) Remove all foreign hardware.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 56, "reputation_required": 3300, "required_quests": ["fq_omni_056"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Remove Tyrant hardware.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm hardware removal.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2300, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_058', false, NULL, NULL, NULL, 'quest_omnicorp.json', 55)
