values ('fq_omni_058', 'Harbinger Mainframe', 'story', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'The Abyss Harbinger is the master process controlling void anomalies. (Location: Void Echo Chasm, Warden AI) Prepare for total system shutdown.', '{"npc_id": "npc_grid_security", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 57, "reputation_required": 175, "required_quests": ["fq_omni_057"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "desc": "Clear system access paths.", "description": "Defeat Aethel Abyssal Reaver (x6)."}, {"type": "kill", "target": "CHRONO_WRAITH", "count": 1, "desc": "Remove temporal lock.", "description": "Defeat Chrono Wraith (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Establish mainframe access.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2400, "items": [{"item_id": "event_horizon_fragment_l", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_059', false, NULL, NULL, NULL, 'quest_omnicorp.json', 56)
