values ('fq_omni_059', 'Fragmenter Process Kill', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'Soul Fragmenters are spawning child processes. (Location: Void Echo Chasm, Warden AI) Execute Process Kill on all Fragmenter processes and subprocesses.', '{"npc_id": "npc_grid_security", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 58, "reputation_required": 3420, "required_quests": ["fq_omni_058"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "desc": "Execute Process Kill on Fragmenters.", "description": "Defeat Soul Fragmenter (x3)."}, {"type": "kill", "target": "VOID_STALKER", "count": 1, "desc": "Kill parent Stalker process.", "description": "Defeat Void Stalker (x1)."}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "brainwave_oscillator", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_060', false, NULL, NULL, NULL, 'quest_omnicorp.json', 57)
