values ('fq_omni_060', 'The Harbinger Shutdown', 'boss', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'FINAL SHUTDOWN SEQUENCE. (Location: Void Echo Chasm, Director Sterling) The Abyss Harbinger is the void''s master process. Execute total system shutdown. Raid Boss Tier-2. All Omnicorp resources authorized. System integrity must be restored.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 59, "reputation_required": 3480, "required_quests": ["fq_omni_059"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "EXECUTE SHUTDOWN ON ABYSS HARBINGER.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "void_core", "count": 1, "desc": "Secure the Shutdown Code for Omnicorp.", "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 2}, {"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_omni_061', false, NULL, NULL, NULL, 'quest_omnicorp.json', 58)
