values ('fq_omni_061', 'Structural Stabilization', 'exploration', 'S', 'OMNICORP', 'SEVERANCE_FAULTLINE', 'The Severance Faultline is a structural integrity failure. Omnicorp will deploy gravity anchors to stabilize the planetary crust. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 60, "reputation_required": 3540, "required_quests": ["fq_omni_060"]}'::jsonb, '[{"type": "travel", "target": "SEVERANCE_FAULTLINE", "count": 1, "desc": "Enter the Severance Faultline.", "description": "Travel to SEVERANCE FAULTLINE. (Travel to: Severance Faultline, Shattered Heart)"}, {"type": "collect", "target": "titan_core", "count": 3, "desc": "Upload structural stability readings.", "description": "Collect titan core (x3). [Item: Titan Core]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1600, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_062', false, NULL, NULL, NULL, 'quest_omnicorp.json', 59)
