values ('fq_omni_062', 'Carapace Deconstruction', 'hunt', 'S', 'OMNICORP', 'SEVERANCE_FAULTLINE', 'Aethel Iron Carapaces contain minerals essential for gravity anchor construction. (Location: Severance Faultline, Tech Officer 404) Deconstruct and extract.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 61, "reputation_required": 3600, "required_quests": ["fq_omni_061"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Deconstruct Iron Carapaces.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "carapace_fragment", "count": 1, "desc": "Report mineral extraction yields.", "description": "Collect carapace fragment (x1). [Item: Carapace Fragment]"}]'::jsonb, '{"exp": 5200, "currency": 2600, "crd": 1300, "rep": 1700, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_063', false, NULL, NULL, NULL, 'quest_omnicorp.json', 60)
