values ('fq_omni_063', 'Tyrant Structural Interference', 'boss', 'S', 'OMNICORP', 'SEVERANCE_FAULTLINE', 'Crystal Tyrants disrupt anchor calibration. (Location: Severance Faultline, Director Sterling) Eliminate interference sources.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 62, "reputation_required": 3660, "required_quests": ["fq_omni_062"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Eliminate Tyrant interference.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm calibration restored.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_064', false, NULL, NULL, NULL, 'quest_omnicorp.json', 61)
