values ('fq_omni_064', 'Jotunn Anchor Site', 'boss', 'S', 'OMNICORP', 'SEVERANCE_FAULTLINE', 'Gigantic Jotunns refuse to vacate anchor deployment sites. (Location: Severance Faultline, Director Sterling) Deploy anchors regardless.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 63, "reputation_required": 3720, "required_quests": ["fq_omni_063"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Deploy anchors at Jotunn sites.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "core_fragment", "count": 3, "desc": "Confirm all anchors deployed.", "description": "Collect core fragment (x3). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2100, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_065', false, NULL, NULL, NULL, 'quest_omnicorp.json', 62)
