values ('fq_omni_065', 'Core Integration Prep', 'exploration', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core will become Omnicorp''s primary server farm. Begin integration assessment. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 64, "reputation_required": 3780, "required_quests": ["fq_omni_064"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "desc": "Enter the Aethel Siphon Core.", "description": "Travel to AETHEL SIPHON CORE. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "void_channeler_core", "count": 2, "desc": "Complete integration assessment.", "description": "Collect void channeler core (x2). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_066', false, NULL, NULL, NULL, 'quest_omnicorp.json', 63)
