values ('fq_omni_066', 'Core Security Sweep', 'hunt', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'Hostile processes detected in Core systems. (Location: Aethel Siphon Core, Warden AI) Execute security sweep.', '{"npc_id": "npc_grid_security", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 65, "reputation_required": 3840, "required_quests": ["fq_omni_065"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "desc": "Execute security sweep.", "description": "Defeat Aethel Abyssal Reaver (x8)."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "desc": "Purge Channeler processes.", "description": "Defeat Aethel Void Channeler (x5)."}]'::jsonb, '{"exp": 5800, "currency": 2900, "crd": 1450, "rep": 1900, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_067', false, NULL, NULL, NULL, 'quest_omnicorp.json', 64)
