values ('fq_omni_067', 'Behemoth System Crash', 'boss', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths cause system crashes in Core infrastructure. (Location: Aethel Siphon Core, Warden AI) Prevent crash cascade.', '{"npc_id": "npc_grid_security", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 3900, "required_quests": ["fq_omni_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Prevent crash cascade.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Confirm system uptime restored.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2000, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_068', false, NULL, NULL, NULL, 'quest_omnicorp.json', 65)
