values ('fq_omni_068', 'Rift Stalker Network', 'hunt', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'Rift Stalkers have established a peer-to-peer network in the Core. (Location: Aethel Siphon Core, Tech Officer 404) Disconnect all nodes.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 67, "reputation_required": 3960, "required_quests": ["fq_omni_067"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "desc": "Disconnect Stalker network nodes.", "description": "Defeat Aethel Rift Stalker (x6)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "desc": "Confirm network disconnected.", "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 6400, "currency": 3200, "crd": 1600, "rep": 2100, "items": [{"item_id": "dark_energy_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_069', false, NULL, NULL, NULL, 'quest_omnicorp.json', 66)
