values ('fq_omni_069', 'Gravity Algorithm', 'story', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'The Gravity Titan''s algorithm can manipulate mass. (Location: Aethel Siphon Core, Director Sterling) Omnicorp will copy that algorithm and deploy it across the network.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 68, "reputation_required": 225, "required_quests": ["fq_omni_068"]}'::jsonb, '[{"type": "collect", "target": "core_fragment", "count": 3, "desc": "Collect Gravity Titan algorithm data.", "description": "Collect core fragment (x3). [Item: Core Fragment]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Eliminate Jotunn data corruption.", "description": "Defeat Gigantic Jotunn (x1)."}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "gravity_well_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_070', false, NULL, NULL, NULL, 'quest_omnicorp.json', 67)
