values ('fq_omni_071', 'Automated Manufacturing', 'exploration', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'The Prima Materia Forge will become Omnicorp''s primary manufacturing facility. Initiate facility takeover. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 70, "reputation_required": 4140, "required_quests": ["fq_omni_070"]}'::jsonb, '[{"type": "travel", "target": "PRIMA_MATERIA_FORGE", "count": 1, "desc": "Enter the Prima Materia Forge.", "description": "Travel to PRIMA MATERIA FORGE. (Travel to: Prima Materia Forge, Shattered Heart)"}, {"type": "collect", "target": "crystal_core", "count": 2, "desc": "Complete manufacturing assessment.", "description": "Collect crystal core (x2). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "raw_aethel_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_072', false, NULL, NULL, NULL, 'quest_omnicorp.json', 69)
