values ('fq_omni_072', 'Defense System Override', 'hunt', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Ancient Forge defenses reject Omnicorp network integration. (Location: Prima Materia Forge, Warden AI) Override with extreme prejudice.', '{"npc_id": "npc_grid_security", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 71, "reputation_required": 4200, "required_quests": ["fq_omni_071"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Override Forge defense systems.", "description": "Defeat Aethel Iron Carapace (x8)."}, {"type": "collect", "target": "crystal_core", "count": 1, "desc": "Confirm all systems overridden.", "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2100, "items": [{"item_id": "rusted_cybernetic_arm", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_073', false, NULL, NULL, NULL, 'quest_omnicorp.json', 70)
