values ('fq_omni_075', 'Jotunn Workflow Termination', 'boss', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Jotunns are interfering with Forge workflow automation. (Location: Prima Materia Forge, Director Sterling) Terminate interfering processes.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 74, "reputation_required": 4380, "required_quests": ["fq_omni_074"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Terminate Jotunn workflow interference.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm workflow optimized.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2400, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_076', false, NULL, NULL, NULL, 'quest_omnicorp.json', 73)
