values ('fq_omni_076', 'Mass Production Protocol', 'hunt', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Initiate Mass Production Protocol. (Location: Prima Materia Forge, Tech Officer 404) All rival presence in the Forge is a production inefficiency.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 75, "reputation_required": 4440, "required_quests": ["fq_omni_075"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "desc": "Clear production floor.", "description": "Defeat Aethel Void Channeler (x6)."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "desc": "Confirm mass production online.", "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2500, "items": [{"item_id": "power_regulator_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_077', false, NULL, NULL, NULL, 'quest_omnicorp.json', 74)
