values ('fq_omni_077', 'Automaton Reprogramming', 'boss', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Titan Forge Automatons resist Omnicorp programming. (Location: Prima Materia Forge, Warden AI) Reprogram through combat override.', '{"npc_id": "npc_grid_security", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 76, "reputation_required": 4500, "required_quests": ["fq_omni_076"]}'::jsonb, '[{"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "desc": "Reprogram Automatons.", "description": "Defeat Titan Forge Automaton (x3)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm reprogramming.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2600, "items": [{"item_id": "processor_cooling_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_078', false, NULL, NULL, NULL, 'quest_omnicorp.json', 75)
