values ('fq_omni_078', 'Proto Core Recycling', 'boss', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Titan Proto Cores are failed products. (Location: Prima Materia Forge, Tech Officer 404) Recycle for raw materials.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 77, "reputation_required": 4560, "required_quests": ["fq_omni_077"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 2, "desc": "Recycle Proto Cores.", "description": "Defeat Titan Proto Core (x2)."}, {"type": "collect", "target": "titan_core", "count": 1, "desc": "Report recycling yield.", "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 9000, "currency": 4500, "crd": 2250, "rep": 2800, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_079', false, NULL, NULL, NULL, 'quest_omnicorp.json', 76)
