values ('fq_omni_079', 'Executive Legend Trial', 'story', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'The Executive Legend certification trial. (Location: Prima Materia Forge, Director Sterling) Eliminate both Titan and Harbinger in one operational cycle. Prove systematic superiority.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 78, "reputation_required": 275, "required_quests": ["fq_omni_078"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Eliminate Titan — target acquired.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Eliminate Harbinger — target acquired.", "description": "Defeat Abyss Harbinger (x1)."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_080', false, NULL, NULL, NULL, 'quest_omnicorp.json', 77)
