values ('fq_omni_080', 'Executive Legend', 'story', 'S', 'OMNICORP', 'THE_SPIRE', 'CEO Valerius personally authorizes your Executive Legend certification. (Location: The Spire, Director Sterling) Return to the Spire for system-wide recognition broadcast.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "THE_SPIRE"}'::jsonb, '{"min_level": 79, "reputation_required": 325, "required_quests": ["fq_omni_079"]}'::jsonb, '[{"type": "travel", "target": "THE_SPIRE", "count": 1, "desc": "Return to the Spire.", "description": "Travel to THE SPIRE. (Travel to: The Spire)"}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Receive Executive Legend certification.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}, {"item_id": "astral_phase_crystal_pure", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_081', false, NULL, NULL, NULL, 'quest_omnicorp.json', 78)
