values ('fq_omni_081', 'Apex Quality Control', 'story', 'S', 'OMNICORP', 'HIDDEN_AETHELGARDIAN_CITY', 'The Hidden Aethelgardian City contains Precursor technology caches. Omnicorp authorizes full technology acquisition. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 80, "reputation_required": 375, "required_quests": ["fq_omni_080"]}'::jsonb, '[{"type": "travel", "target": "HIDDEN_AETHELGARDIAN_CITY", "count": 1, "desc": "Enter the Hidden Aethelgardian City.", "description": "Travel to HIDDEN AETHELGARDIAN CITY. (Travel to: Hidden Aethelgardian City)"}, {"type": "collect", "target": "monster_material", "count": 3, "desc": "Acquire Precursor technology caches.", "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_082', false, NULL, NULL, NULL, 'quest_omnicorp.json', 79)
