values ('fq_omni_082', 'City Defense Removal', 'hunt', 'S', 'OMNICORP', 'HIDDEN_AETHELGARDIAN_CITY', 'City defenses are incompatible with Omnicorp protocols. (Location: Hidden Aethelgardian City, Warden AI) Remove legacy defense systems.', '{"npc_id": "npc_grid_security", "name": "", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 81, "reputation_required": 4800, "required_quests": ["fq_omni_081"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 8, "desc": "Remove legacy defense systems.", "description": "Defeat Aethel Rift Stalker (x8)."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 3, "desc": "Confirm sectors secured.", "description": "Collect raw aethel fragment (x3). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 8500, "currency": 4200, "crd": 2100, "rep": 2700, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_083', false, NULL, NULL, NULL, 'quest_omnicorp.json', 80)
