values ('fq_omni_083', 'Tech Database Download', 'collect', 'S', 'OMNICORP', 'HIDDEN_AETHELGARDIAN_CITY', 'The City holds a Precursor tech database. (Location: Hidden Aethelgardian City, Tech Officer 404) Download all data for Omnicorp R&D.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 82, "reputation_required": 4860, "required_quests": ["fq_omni_082"]}'::jsonb, '[{"type": "collect", "target": "raw_aethel_fragment", "count": 5, "desc": "Download Precursor tech database.", "description": "Collect raw aethel fragment (x5). [Item: Raw Aethel Fragment]"}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "desc": "Defend download from data thieves.", "description": "Defeat Aethel Abyssal Reaver (x4)."}]'::jsonb, '{"exp": 8800, "currency": 4400, "crd": 2200, "rep": 2800, "items": [{"item_id": "memory_fragment_chip", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_084', false, NULL, NULL, NULL, 'quest_omnicorp.json', 81)
