values ('fq_omni_084', 'Apex Drake Deletion', 'boss', 'S', 'OMNICORP', 'SHATTERED_HEART', 'The Apex Ashen Drake is a legacy biological process. (Location: Shattered Heart, Director Sterling) Execute permanent deletion.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 83, "reputation_required": 4920, "required_quests": ["fq_omni_083"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Execute permanent Drake deletion.", "description": "Defeat Ashen Drake (x1)."}, {"type": "collect", "target": "ancient_scale", "count": 1, "desc": "Verify deletion.", "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "ancient_scale", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_085', false, NULL, NULL, NULL, 'quest_omnicorp.json', 82)
