values ('fq_omni_088', 'Core Integration', 'exploration', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is now Omnicorp Central Server. Complete full systems integration. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 87, "reputation_required": 5160, "required_quests": ["fq_omni_087"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "desc": "Enter Omnicorp Central Server.", "description": "Travel to AETHEL SIPHON CORE. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "monster_material", "count": 5, "desc": "Deploy integration beacons.", "description": "Collect monster material (x5). [Item: Monster Material]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "power_regulator_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_089', false, NULL, NULL, NULL, 'quest_omnicorp.json', 86)
