values ('fq_omni_089', 'World Engine Source Code', 'story', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'The World Engine is the ultimate source code. (Location: Aethel Siphon Core, Director Sterling) Omnicorp will acquire exclusive access.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 88, "reputation_required": 425, "required_quests": ["fq_omni_088"]}'::jsonb, '[{"type": "collect", "target": "monster_material", "count": 3, "desc": "Obtain source code access keys.", "description": "Collect monster material (x3). [Item: Monster Material]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 2, "desc": "Remove source code guards.", "description": "Defeat Gigantic Jotunn (x2)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_090', false, NULL, NULL, NULL, 'quest_omnicorp.json', 87)
