values ('fq_omni_090', 'Source Code Compile', 'story', 'S', 'OMNICORP', 'AETHEL_SIPHON_CORE', 'Compile the World Engine source code. (Location: Aethel Siphon Core, Warden AI) Omnicorp''s greatest software deployment. Defend the compile process.', '{"npc_id": "npc_grid_security", "name": "", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 89, "reputation_required": 475, "required_quests": ["fq_omni_089"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Defend compile process.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "desc": "Remove compile errors.", "description": "Defeat Crystal Tyrant (x2)."}, {"type": "collect", "target": "void_channeler_core", "count": 1, "desc": "Confirm successful compile.", "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_omni_091', false, NULL, NULL, NULL, 'quest_omnicorp.json', 88)
