values ('fq_omni_091', 'Final System Cleanup', 'hunt', 'S', 'OMNICORP', 'SEVERANCE_FAULTLINE', 'The compiled Engine flushes residual errors. (Location: Severance Faultline, Director Sterling) Execute final system cleanup at the Faultline.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 90, "reputation_required": 5340, "required_quests": ["fq_omni_090"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 5, "desc": "Execute Jotunn cleanup.", "description": "Defeat Gigantic Jotunn (x5)."}, {"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "desc": "Execute Carapace cleanup.", "description": "Defeat Aethel Iron Carapace (x8)."}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_092', false, NULL, NULL, NULL, 'quest_omnicorp.json', 89)
