values ('fq_omni_092', 'Void System Purge', 'hunt', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'The void is a deprecated system. (Location: Void Echo Chasm, Warden AI) Purge all remaining void instances permanently.', '{"npc_id": "npc_grid_security", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 91, "reputation_required": 5400, "required_quests": ["fq_omni_091"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "desc": "Purge Abyssal instances.", "description": "Defeat Aethel Abyssal Reaver (x10)."}, {"type": "kill", "target": "VOID_REAVER", "count": 10, "desc": "Purge Void instances.", "description": "Defeat Void Reaver (x10)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_093', false, NULL, NULL, NULL, 'quest_omnicorp.json', 90)
