values ('fq_omni_093', 'Tyrant Legacy Removal', 'boss', 'S', 'OMNICORP', 'SHATTERED_HEART', 'Crystal Tyrants are legacy hardware. (Location: Shattered Heart, Director Sterling) Execute legacy hardware removal.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 92, "reputation_required": 5460, "required_quests": ["fq_omni_092"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 3, "desc": "Remove legacy Tyrant hardware.", "description": "Defeat Crystal Tyrant (x3)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm legacy removal.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 4}], "reputation": 50}'::jsonb, false, false, 'fq_omni_094', false, NULL, NULL, NULL, 'quest_omnicorp.json', 91)
