values ('fq_omni_094', 'Forge Final Production', 'hunt', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Final Forge production cycle. (Location: Prima Materia Forge, Tech Officer 404) Eliminate all variables that could impact production efficiency.', '{"npc_id": "npc_omnicorp_technician", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 93, "reputation_required": 5520, "required_quests": ["fq_omni_093"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 8, "desc": "Eliminate production variables.", "description": "Defeat Aethel Void Channeler (x8)."}, {"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "desc": "Replace legacy Automatons.", "description": "Defeat Titan Forge Automaton (x3)."}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "raw_aethel_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_095', false, NULL, NULL, NULL, 'quest_omnicorp.json', 92)
