values ('fq_omni_095', 'Expanse Network Control', 'hunt', 'S', 'OMNICORP', 'CRADLE_EXPANSE', 'The Cradle Expanse is now Omnicorp-managed territory. Enforce network control protocols. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 94, "reputation_required": 5580, "required_quests": ["fq_omni_094"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 10, "desc": "Enforce network control.", "description": "Defeat Aethel Rift Stalker (x10)."}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Remove remaining Titan instance.", "description": "Defeat Gravity Titan (x1)."}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_096', false, NULL, NULL, NULL, 'quest_omnicorp.json', 93)
