values ('fq_omni_096', 'Orbital System Maintenance', 'hunt', 'S', 'OMNICORP', 'ORBITAL_SENTINEL_COMMAND', 'Orbital systems require quarterly maintenance. (Location: Orbital Sentinel Command, Director Sterling) Clear all orbital sectors of hostile elements.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 95, "reputation_required": 5640, "required_quests": ["fq_omni_095"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 10, "desc": "Execute orbital maintenance sweep.", "description": "Defeat Aethel Iron Carapace (x10)."}, {"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "desc": "Remove orbital system errors.", "description": "Defeat Aethel Corrupted Behemoth (x3)."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 3800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_omni_097', false, NULL, NULL, NULL, 'quest_omnicorp.json', 94)
