values ('fq_omni_097', 'Final System Backup', 'story', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Execute final system backup before singularity. (Location: Prima Materia Forge, Warden AI) Eliminate all threats to backup integrity.', '{"npc_id": "npc_grid_security", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 96, "reputation_required": 525, "required_quests": ["fq_omni_096"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "desc": "Eliminate backup threats.", "description": "Defeat Gigantic Jotunn (x3)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Eliminate Harbinger backup corruption.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "core_fragment", "count": 1, "desc": "Confirm backup complete.", "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_omni_098', false, NULL, NULL, NULL, 'quest_omnicorp.json', 95)
