values ('fq_omni_098', 'The Final Override', 'story', 'S', 'OMNICORP', 'PRIMA_MATERIA_FORGE', 'Execute the Final Override. (Location: Prima Materia Forge, Director Sterling) Terminate Jotunn, Drake, and Harbinger processes. All system authority transfers to Omnicorp.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 97, "reputation_required": 575, "required_quests": ["fq_omni_097"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "desc": "Override Jotunn authority.", "description": "Defeat Gigantic Jotunn (x1)."}, {"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "desc": "Override Drake authority.", "description": "Defeat Ashen Drake (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Override Harbinger authority.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "monster_material", "count": 1, "desc": "Confirm Final Override.", "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 7000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "titan_core", "quantity": 3}, {"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_omni_099', false, NULL, NULL, NULL, 'quest_omnicorp.json', 96)
