values ('fq_omni_099', 'The Singularity', 'story', 'S', 'OMNICORP', 'VOID_ECHO_CHASM', 'The deepest Void Echo Chasm. Defeat the Eternal forms of Titan and Harbinger. All system resources converge on this moment. The Singularity awaits. Quest giver: Director Sterling at The Spire Executive Floor.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 98, "reputation_required": 625, "required_quests": ["fq_omni_098"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "desc": "Enter the deepest chasm.", "description": "Travel to VOID ECHO CHASM. (Travel to: Void Echo Chasm)"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "desc": "Terminate Eternal Gravity Titan.", "description": "Defeat Gravity Titan (x1)."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "desc": "Terminate Eternal Abyss Harbinger.", "description": "Defeat Abyss Harbinger (x1)."}, {"type": "collect", "target": "void_core", "count": 1, "desc": "CLAIM THE SINGULARITY SEAL.", "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 25000, "currency": 12000, "crd": 6000, "rep": 8000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_omni_100', false, NULL, NULL, NULL, 'quest_omnicorp.json', 97)
